14	 * in {@link OwnerRepository#findAll()}, so the count is correct in the create pipeline — where the
15	 * owner has been stamped with its household id but not yet persisted — as well as on reads.
16	 *
17	 * <p>Wired into both the create pipeline (after {@link AssignOwnerHousehold} has stamped the
18	 * shared id) and the single-owner GET pipeline. Like {@code bulkSignupWarning} the value is
19	 * transient and set on the in-flight owner so the responder carries it; it is not persisted.
20	 */
21	public class DeriveOwnerHouseholdSize {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        String householdId = owner.getHouseholdId();
25	        if (householdId == null) {
26	            owner.setHouseholdSize(1);
27	            return;
28	        }
29	        long count = 1; // the owner itself
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
32	                continue;
33	            }
34	            if (householdId.equals(existing.getHouseholdId())) {
35	                count++;
36	            }
37	        }
38	        owner.setHouseholdSize((int) count);
39	    }
40	}
